/* Original Grade 2 activities. Three bounded examples revisit each idea.
   Every response uses picture controls or choices; no answer typing is needed. */
const M = (suffix, title, topicId, unit, conceptKey, standards, goal, prerequisite, workedExample, explainPrompt, reviewPrompt) => ({
  id: `g2y-${suffix}`, title, bandId: 'early', gradeIds: ['2'], topicId, unitId: `g2-unit-${unit}`, conceptKey, conceptId: conceptKey,
  worldId: ['geometry', 'measuring', 'data', 'measurement'].includes(topicId) ? 'studio' : topicId === 'fractions' ? 'garden' : 'meadow',
  standards, sourceIds: [], lessonId: null, minutes: 8, goal, skill: goal,
  teacherNotes: 'Explore with a grown-up. Build a model, talk about what each unit means, and revisit another example. Supported practice counts as participation.',
  lessonPlan: { goal, prerequisite, workedExample, explainPrompt, reviewPrompt }
});

